import{z as B,x as n,o as r,c as p,q as A,j as s,D as E,d as e,s as o,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"管理期货风险平价","description":"","frontmatter":{"title":"管理期货风险平价","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mfd-risk-parity.md","filePath":"quant/mfd-risk-parity.md","lastUpdated":1791063341000}'),m={name:"quant/mfd-risk-parity.md"};function d(h,a,C,D,P,T){const i=n("Mermaid");return r(),p("div",null,[a[2]||(a[2]=A('<h1 id="管理期货风险平价" tabindex="-1">管理期货风险平价 <a class="header-anchor" href="#管理期货风险平价" aria-label="Permalink to &quot;管理期货风险平价&quot;">​</a></h1><div class="epigraph"><p>风险平价把风险预算均分给底层资产类的多头溢价；管理期货把同一套期货工具写成时变多空的趋势。两者可以共用波动缩放，却不是同一个组合。</p><footer>—— 对照 Hurst, Ooi &amp; Pedersen 对趋势跟踪的长样本证据；风险平价实践见桥水 / AQR 一脉的风险预算论述</footer></div><p><a href="/quant/crisis-alpha">危机 alpha</a>把凸性收在路径依赖与保费上。风险平价（risk parity）按风险贡献而不是按名义资本来配股、债、商品、信用：低波动的债券拿到更大名义，以求各类对总波动的贡献接近。管理期货（managed futures, CTA）用趋势符号在同一期货池里做多或做空，再按波动缩放。把二者写进一个账户，是机构常见的「全天候 + 危机凸性」拼盘。问题是它们的杠杆、相关与失败模式会缠在一起：都用 \\(1/\\sigma\\)，都会在波动跳升时去杠杆，股指腿可能重复。本篇写合成规则、风险预算如何分给 MFD 与 RP，以及何时这个拼盘只是加倍的 vol target。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯风险平价在增长崩溃且宽松的危机里，债券腿往往救命；在 2022 年一类股债同跌、波动齐升的通胀危机里，两类多头一起亏，vol target 再砍仓，回撤可以很难看。CTA 的<a href="/quant/crisis-alpha">危机 alpha</a> 恰恰声称能在持续压力里翻空股票。直觉上互补。需要写成可检验的句子：在预先定义的窗口里，RP+MFD 的最大回撤与条件夏普是否优于同等波动的纯 RP，以及代价是否为震荡年的 CTA 磨损。</p><p><span class="marginnote">术语翻译：风险平价不是「钱各买一半」，而是「风险各占一半」。债券年化波动大约只有股票的三分之一，要让两者对组合总波动的贡献相等，债券的名义仓位就得是股票的三倍上下——所以 RP 组合在账面上天生重仓债券，这是风险的算术，不是观点。</span></p><p>第二个问题是重复暴露。RP 已经超配债券名义；CTA 在降息趋势里也会多债券。股指上，RP 永远偏多，CTA 有时空——这是真正的对冲。商品上两者都可能正，且都吃展期。合成前必须按腿对账，而不是看两个产品低相关就相加。</p><h3 id="风险预算-把趋势当成一类资产-而不是「再平衡余量」" tabindex="-1">风险预算：把趋势当成一类资产，而不是「再平衡余量」 <a class="header-anchor" href="#风险预算-把趋势当成一类资产-而不是「再平衡余量」" aria-label="Permalink to &quot;风险预算：把趋势当成一类资产，而不是「再平衡余量」&quot;">​</a></h3><p>设目标组合波动为 \\(\\sigma_{\\mathrm{port}}\\)。一种干净的分法是：先给管理期货一个风险份额 \\(\\pi_{\\mathrm{MFD}}\\)（例如 20%–40% 的风险预算），剩余 \\(1-\\pi\\) 给风险平价多头。每一块内部再做各自的等风险。不要先做满 RP 再用「剩余保证金」去叠 CTA——保证金是约束不是预算，剩余会在平静期膨胀、在压力期消失，使 \\(\\pi_{\\mathrm{MFD}}\\) 变成最错误的时变。</p> \\[\\sigma_{\\mathrm{port}}^2 \\approx \\pi^2\\sigma_{\\mathrm{MFD}}^2 +(1-\\pi)^2\\sigma_{\\mathrm{RP}}^2 +2\\pi(1-\\pi)\\rho\\,\\sigma_{\\mathrm{MFD}}\\sigma_{\\mathrm{RP}}. \\]<p>全样本 \\(\\rho\\) 往往很低；压力期 \\(\\rho\\) 会因共同 vol target 而上升。应用压力 \\(\\rho\\) 来反推 \\(\\pi\\)，而不是用宣传册上的 0.1。</p><p><span class="marginnote">数字实例：取 \\(\\pi_{\\mathrm{MFD}}=0.3\\)、\\(\\sigma_{\\mathrm{MFD}}=10\\%\\)、\\(\\sigma_{\\mathrm{RP}}=8\\%\\)、压力相关 \\(\\rho=0.4\\)，代入公式得 \\(\\sigma_{\\mathrm{port}}^2\\approx 0.0009+0.0031+0.0013=0.0054\\)，即约 \\(7.3\\%\\)。若用全样本 \\(\\rho=0.1\\) 代替，算出的组合波动更低——按它加杠杆，压力一来就会超标。</span></p><p><span class="marginnote">「管理期货风险平价」有时被用来指 CTA 内部的等风险配权，有时指 RP 组合外挂 CTA。两者杠杆含义不同。本文指后者：多资产风险平价与 CTA 的组合层合成。前者见波动缩放与跨资产趋势相关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>RP 块：股指、国债、信用、商品的多头期货或掉期，类内 \\(1/\\sigma\\)，类间等风险或明确超配抗通胀/抗通缩。MFD 块：TSMOM 或多尺度趋势，合约层 \\(1/\\sigma\\)，组合层目标波动独立校准。合成：用压力相关把两块缩放到 \\(\\sigma_{\\mathrm{port}}\\)；对股指、久期、商品的净 beta 设限额，超出则先砍重复的那一侧（通常是 RP 的股指或 CTA 的商品），而不是按比例同时砍——按比例会把危机里真正提供负相关的腿一起削弱。</p><p>回测对照：纯 RP、纯 CTA、50/50 风险预算、以及「RP 用全样本相关、忽略压力相关」的错误合成。验收窗口至少包括：2008 类通缩去杠杆、2013 类利率意外、2020 类短促崩溃与反弹、2022 类股债双杀。每一窗口分别看两块贡献。</p><h3 id="共同-vol-target-是隐形高相关" tabindex="-1">共同 vol target 是隐形高相关 <a class="header-anchor" href="#共同-vol-target-是隐形高相关" aria-label="Permalink to &quot;共同 vol target 是隐形高相关&quot;">​</a></h3><p>两块都在 \\(\\hat\\sigma\\) 上升时降杠杆，等于在组合层面对全球波动做空。这在 Moreira–Muir 意义上可能提高无条件夏普，也在拥挤意义上制造同步减仓。工程响应：两块的波动估计窗错开（例如 RP 用更慢的 \\(\\sigma\\)，CTA 用更快的 \\(\\sigma\\)），或对总杠杆设独立于两块的上限，由组合层一次缩放，避免 \\(1/\\sigma\\) 乘两次。保证金在期货账户里是共用的，必须按最坏相关估占用，不能按块加总后再乘 0.7 的「分散化折扣」而不做压力。</p><p><span class="marginnote">常见误区：「两个产品回测相关只有 0.1，直接拼起来就分散了。」实际上两块各自内置 \\(1/\\sigma\\) 缩放，波动一跳升就同时去杠杆，压力日相关会跳到远高于全样本的水平。判断拼盘要看压力日的同步行为，不是看平静年份的月度相关表。</span></p>',19)),(r(),s(l,null,{default:E(()=>[o(i,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20RP%5B%22%E9%A3%8E%E9%99%A9%E5%B9%B3%E4%BB%B7%E5%A4%9A%E5%A4%B4%E5%9D%97%22%5D%20--%3E%20NET%5B%22%E5%87%80%20beta%20%2F%20%E4%B9%85%E6%9C%9F%20%2F%20%E5%95%86%E5%93%81%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20MFD%5B%22%E7%AE%A1%E7%90%86%E6%9C%9F%E8%B4%A7%E8%B6%8B%E5%8A%BF%E5%9D%97%22%5D%20--%3E%20NET%0A%20%20NET%20--%3E%20PI%5B%22%E5%8E%8B%E5%8A%9B%E7%9B%B8%E5%85%B3%E4%B8%8B%E7%9A%84%E9%A3%8E%E9%99%A9%E4%BB%BD%E9%A2%9D%20%CF%80%22%5D%0A%20%20VOL%5B%22%E4%B8%A4%E5%9D%97%E7%9A%84%201%2F%CF%83%22%5D%20--%3E%20CAP%5B%22%E7%BB%84%E5%90%88%E5%B1%82%E6%80%BB%E6%9D%A0%E6%9D%86%E4%B8%8A%E9%99%90%22%5D%0A%20%20PI%20--%3E%20CAP%0A%20%20CAP%20--%3E%20OUT%5B%22RP%20%2B%20MFD%20%E7%BB%84%E5%90%88%22%5D%0A%20%20OUT%20--%3E%20TEST%5B%22%E9%80%9A%E7%BC%A9%20%2F%20%E9%80%9A%E8%83%80%20%2F%20V%20%E5%9E%8B%E7%AA%97%E5%8F%A3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"RP 卖的是风险溢价的分散持有：股权溢价、期限溢价、可能还有商品与信用。其脆弱性是溢价在同一宏观状态下一起为负。MFD 卖的是趋势可预测性与危机路径上的凸性，脆弱性是震荡与突然反转。互补来自状态或有：增长崩溃时 CTA 空股、RP 靠债券；通胀趋势里 CTA 空债或多商品，补 RP 的久期伤口。不互补的状态是「无趋势的高波动」：两块都磨损，vol target 再把未来的风险溢价暴露砍掉。",-1)),(r(),s(l,null,{default:E(()=>[o(i,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%7B%22%E5%AE%8F%E8%A7%82%E7%8A%B6%E6%80%81%E6%98%AF%E5%93%AA%E4%B8%80%E7%A7%8D%EF%BC%9F%22%7D%20--%3E%20A%5B%22%E9%80%9A%E7%BC%A9%E8%A1%B0%E9%80%80%EF%BC%9ARP%20%E5%80%BA%E5%88%B8%E8%85%BF%E6%95%91%E5%91%BD%EF%BC%8CCTA%20%E7%A9%BA%E8%82%A1%22%5D%0A%20%20S%20--%3E%20B%5B%22%E9%80%9A%E8%83%80%E8%82%A1%E5%80%BA%E5%8F%8C%E6%9D%80%EF%BC%9ARP%20%E4%B9%85%E6%9C%9F%E5%8F%97%E4%BC%A4%EF%BC%8C%E9%9C%80%20CTA%20%E7%A9%BA%E5%80%BA%E6%88%96%E5%A4%9A%E5%95%86%E5%93%81%22%5D%0A%20%20S%20--%3E%20C%5B%22%E5%B9%B3%E7%A8%B3%E5%A2%9E%E9%95%BF%EF%BC%9A%E4%B8%A4%E5%9D%97%E5%90%8C%E6%AD%A3%EF%BC%8C%E5%85%A8%E6%A0%B7%E6%9C%AC%E7%9B%B8%E5%85%B3%E6%98%BE%E5%BE%97%E5%BE%88%E4%BD%8E%22%5D%0A%20%20S%20--%3E%20D%5B%22%E6%97%A0%E8%B6%8B%E5%8A%BF%E9%AB%98%E6%B3%A2%E5%8A%A8%EF%BC%9A%E4%B8%A4%E5%9D%97%E9%83%BD%E7%A3%A8%E6%8D%9F%EF%BC%8Cvol%20target%20%E5%86%8D%E7%A0%8D%E4%BB%93%22%5D%0A%20%20A%20--%3E%20E%5B%22%E4%BA%92%E8%A1%A5%E5%8F%AA%E5%9C%A8%E7%89%B9%E5%AE%9A%E7%8A%B6%E6%80%81%E5%85%91%E7%8E%B0%22%5D%0A%20%20B%20--%3E%20E%0A%20%20D%20--%3E%20F%5B%22%E6%8B%BC%E7%9B%98%E9%80%80%E5%8C%96%E6%88%90%E5%8A%A0%E5%80%8D%E7%9A%84%20vol%20target%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p>资金层面，两块都是杠杆期货，融资与保证金螺旋相同，见 Brunnermeier–Pedersen。拼盘没有消除中介约束，只是改变了方向性。拥挤上，RP 与 CTA 的投资者基础不同，但执行日可能重叠（波动跳升日）。合成产品的容量按重叠日的 \\(Q/D\\) 估，不要按两块 AUM 相加估。</p><h3 id="展期与债券-carry-会被两边各记一次" tabindex="-1">展期与债券 Carry 会被两边各记一次 <a class="header-anchor" href="#展期与债券-carry-会被两边各记一次" aria-label="Permalink to &quot;展期与债券 Carry 会被两边各记一次&quot;">​</a></h3><p>RP 的商品多头吃被动展期；CTA 的商品趋势含总收益里的展期。RP 的债券超配吃 roll-down；CTA 的债券趋势在降息周期同向。归因若只看产品级夏普，会以为有四条 alpha，实际可能是两条溢价被两个规则重复加载。应强制分列：RP 的静态溢价、CTA 的方向切换、以及曲线 Carry 的单独账，见<a href="/quant/ts-carry">期限结构 Carry</a> 与<a href="/quant/trend-vs-roll">趋势对展期</a>。</p><p><span class="marginnote">把拼盘叫做「全天候」并不自动覆盖股债双杀。全天候的原意是对增长与通胀四种天气做风险均衡；CTA 是第五个天气——趋势是否存在。没有趋势的通胀冲击，拼盘仍可能只是杠杆多头。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用剩余保证金决定 CTA 权重。不要用全样本低相关给 \\(\\pi_{\\mathrm{MFD}}\\) 加杠杆。不要在同一经纪商账户里让两块独立 vol target 而不设总闸。国内可交易的债券与股指期货工具集更窄，RP 的「四类天气」与 CTA 的空头腿都可能残缺，拼盘要按当地工具重新定义，而不是把全球回测换汇。</p><p>与纯风险平价、纯 CTA 的选择：若投资者的危机定义是慢熊，CTA 份额可以更高；若主要怕通胀下的股债同跌，应检查 CTA 是否真能空久期，而不是假设「管理期货总会救场」。产品层把 MFD 风险平价当成一个词出售时，尽调附件必须有净暴露路径。</p><p><span class="marginnote">出处：趋势长样本见 Hurst, Ooi &amp; Pedersen, <em>A Century of Evidence on Trend-Following Investing</em>；TSMOM 见 Moskowitz, Ooi &amp; Pedersen, JFE, 2012。危机验收见 Kaminski。风险平价作为风险预算方法属于桥梁水与后续量化实践，不要把某一家的商标当成论文定义。波动管理见 Moreira and Muir, JF, 2017。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>管理期货风险平价指用风险份额合成「多头风险平价」与「趋势 CTA」，不是 CTA 内部等权的别名。</li><li>互补来自危机路径上的方向切换；共同 vol target 与重复的债、商品腿会削弱互补。</li><li>\\(\\pi\\) 应用压力相关校准，总杠杆只在组合层缩放一次，保证金按最坏占用估。</li><li>归因要拆开静态溢价、趋势切换与展期，防止两条溢价被记成四条 alpha。</li><li>出处：Hurst–Ooi–Pedersen；Moskowitz et al., 2012；Kaminski；Moreira–Muir, 2017。</li></ul>',10))])}const g=B(m,[["render",d]]);export{u as __pageData,g as default};
